function executeReadyCampaign(
    Commitment calldata c,
    bytes calldata creatorSignature,
    CloseReceipt calldata r,
    bytes calldata finalizerSignature,
    ReadinessReceipt calldata ready,
    bytes calldata readinessSignature,
    bytes calldata controllerCreationCode
) external payable returns (address controller, address token, address curve, address feeShare) {
    uint256 balanceBefore = address(this).balance - msg.value;
    if (block.chainid != ROBINHOOD_CHAIN_ID) revert WrongChain();
    if (controllerForCampaign[c.campaignId] != address(0)) revert CampaignAlreadyDeployed();
    if (c.campaignId == bytes32(0) || c.constitutionHash == bytes32(0) || c.compilerHash == bytes32(0)
        || c.providerConfigHash == bytes32(0) || c.creator == address(0) || c.rootFinalizer == address(0)
        || c.bagsFactory == address(0) || c.weth == address(0) || c.bagsLens == address(0)
        || c.expectedHook == address(0) || c.swapAdapter == address(0)
        || c.operatingFeeRecipient == address(0) || c.minimumClaimGross == 0
        || c.capacities[0] == 0 || c.capacities[1] == 0 || c.capacities[2] == 0
        // A creator cannot be asked to re-sign when a later provider-ready
        // or permissionless launch is delayed. Campaign/factory/nonce bind
        // replay; the one signature has no post-close expiry.
        || c.closeAt == 0 || c.validUntil != type(uint64).max
        || bytes(c.tokenName).length == 0 || bytes(c.tokenSymbol).length == 0
        || bytes(c.metadataURI).length == 0) revert InvalidCommitment();
    bytes32 expectedProviderHash = keccak256(abi.encode(
        c.bagsFactory, c.partner, c.weth, c.bagsLens, c.expectedHook, c.swapAdapter
    ));
    if (c.providerConfigHash != expectedProviderHash) revert InvalidCommitment();
    bytes32 boundCommitmentHash = commitmentHash(c);
    if (_recover(_personalDigest(boundCommitmentHash), creatorSignature) != c.creator) revert SignatureInvalid();

    if (r.campaignId != c.campaignId || r.commitmentHash != boundCommitmentHash
        || r.constitutionHash != c.constitutionHash || r.compilerHash != c.compilerHash
        || r.providerConfigHash != c.providerConfigHash || r.finalizer != c.rootFinalizer
        || r.capacity != c.capacities[0] || r.closeAt != c.closeAt
        || r.acceptedCount == 0 || r.acceptedCount > r.capacity
        || r.prelaunchRoot == bytes32(0) || r.evidenceManifestHash == bytes32(0)) revert InvalidCloseReceipt();
    if (r.closeReason == CLOSED_BY_CAPACITY) {
        if (r.acceptedCount != r.capacity || r.cutoff > c.closeAt) revert InvalidCloseReceipt();
    } else if (r.closeReason == CLOSED_BY_DEADLINE) {
        if (r.cutoff != c.closeAt || block.timestamp < c.closeAt) revert InvalidCloseReceipt();
    } else revert InvalidCloseReceipt();
    bytes32 boundCloseHash = closeReceiptHash(r);
    if (_recover(_personalDigest(boundCloseHash), finalizerSignature) != c.rootFinalizer) revert SignatureInvalid();

    if (ready.campaignId != c.campaignId || ready.commitmentHash != boundCommitmentHash
        || ready.closeReceiptHash != boundCloseHash || ready.constitutionHash != c.constitutionHash
        || ready.compilerHash != c.compilerHash || ready.providerConfigHash != c.providerConfigHash
        || ready.authorityManifestHash != BAGS_AUTHORITY_MANIFEST_SHA256
        || ready.authorityManifestVersion != BAGS_AUTHORITY_MANIFEST_VERSION
        || ready.providerEvidenceHash == bytes32(0) || ready.simulationHash == bytes32(0)
        || ready.finalizer != c.rootFinalizer) revert InvalidReadinessReceipt();
    if (_recover(_personalDigest(readinessReceiptHash(ready)), readinessSignature) != c.rootFinalizer) {
        revert SignatureInvalid();
    }
    if (block.number == 0 || ready.observedBlockNumber >= block.number
        || ready.observedBlockHash == bytes32(0)
        || blockhash(ready.observedBlockNumber) != ready.observedBlockHash) revert StaleReadiness();
    _checkProvider(c, ready);

    // Transported bytes are never authority: the Factory generation pins the
    // complete bare creation template and constructs every business argument.
    if (controllerCreationCode.length == 0 || keccak256(controllerCreationCode) != controllerCreationCodeHash) {
        revert InvalidControllerTemplate();
    }
    bytes memory constructorArguments = abi.encode(c, r);
    uint256 initcodeLength = controllerCreationCode.length + constructorArguments.length;
    if (initcodeLength > 49_152) revert ControllerInitcodeTooLarge(initcodeLength);
    bytes memory initcode = abi.encodePacked(controllerCreationCode, constructorArguments);
    assembly ("memory-safe") {
        controller := create(0, add(initcode, 0x20), mload(initcode))
    }
    if (controller == address(0)) revert ControllerDeploymentFailed();
    controllerForCampaign[c.campaignId] = controller;
    emit CampaignReady(c.campaignId, controller, boundCommitmentHash, r.prelaunchRoot, r.evidenceManifestHash);
    (token, curve, feeShare) = IAtomicLaunchControllerV02(controller).launch{value: msg.value}();
    uint256 refund = address(this).balance - balanceBefore;
    if (refund != 0) {
        (bool ok,) = msg.sender.call{value: refund}("");
        if (!ok) revert RefundFailed();
    }
    emit CampaignExecuted(c.campaignId, controller, token, curve, feeShare);
}

const contracts = Object.freeze({
  factory: ["BermCampaignFactoryV02.sol", "BermCampaignFactoryV02"],
  controller: ["BermRobinhoodAtomicLaunchControllerV02.sol", "BermRobinhoodAtomicLaunchControllerV02"],
  distributor: ["BermRobinhoodDistributorV02.sol", "BermRobinhoodDistributorV02"],
  swapAdapter: ["BagsRobinhoodDualPhaseBuyAdapterV02.sol", "BagsRobinhoodDualPhaseBuyAdapterV02"],
});

uint8 public constant PRELAUNCH = 0;
uint8 public constant GRADUATION = 1;
uint8 public constant FOMO = 2;
uint8 public constant COHORT_COUNT = 3;

uint32 public immutable prelaunchCapacity;
uint32 public immutable graduationCapacity;
uint32 public immutable fomoCapacity;
uint32 public immutable founderFilled;

function appendAssignment(uint8 cohortId, bytes32 npubRaw, address wallet, bytes32 evidenceHash) external {
    if (msg.sender != configuredRootFinalizer) revert Unauthorized();
    if (!launchBound) revert LaunchNotBound();
    if (npubRaw == bytes32(0) || wallet == address(0) || evidenceHash == bytes32(0)) revert InvalidConfiguration();
    uint32 slotIndex;
    if (cohortId == GRADUATION) {
        if (graduatedActive || graduationClosed) revert CohortClosed();
        slotIndex = graduationFilled;
        if (slotIndex >= graduationCapacity) revert CohortClosed();
        graduationFilled = slotIndex + 1;
        if (graduationFilled == graduationCapacity) {
            graduationClosed = true;
            emit GraduationCohortClosed(graduationFilled, graduationCapacity, false);
        }
    } else if (cohortId == FOMO) {
        if (!graduatedActive) revert CohortNotOpen();
        slotIndex = fomoFilled;
        if (slotIndex >= fomoCapacity) revert CohortClosed();
        fomoFilled = slotIndex + 1;
    } else revert InvalidCohort();

    bytes32 identityHash = keccak256(abi.encode(campaignId, npubRaw));
    if (identityAssigned[identityHash]) revert DuplicateIdentity();
    identityAssigned[identityHash] = true;
    assignments[cohortId][slotIndex] = Assignment(npubRaw, wallet, evidenceHash);
    claimStates[identityHash] = ClaimState(true, cohortId, slotIndex, wallet, 0);
    emit LaterSlotAssigned(cohortId, slotIndex, npubRaw, wallet, evidenceHash);
}

function leafHash(uint8 cohortId, uint32 slotIndex, uint32 count, bytes32 npubRaw, address wallet)
    public
    view
    returns (bytes32)
{
    return keccak256(
        abi.encodePacked(
            bytes1(0x00),
            abi.encode(ENCODING_VERSION, CHAIN_DOMAIN, campaignId, cohortId, slotIndex, count, npubRaw, wallet)
        )
    );
}

function _nodeHash(bytes32 left, bytes32 right) internal pure returns (bytes32) {
    return left < right
        ? keccak256(abi.encodePacked(bytes1(0x01), left, right))
        : keccak256(abi.encodePacked(bytes1(0x01), right, left));
}

function _verifyProof(bytes32 leaf, bytes32[] calldata proof, bytes32 root) internal pure returns (bool) {
    bytes32 node = leaf;
    for (uint256 i = 0; i < proof.length; ++i) {
        node = _nodeHash(node, proof[i]);
    }
    return node == root;
}

function buildLevels(leaves) {
  const levels = [leaves];
  let nodeHashCount = 0;
  while (levels.at(-1).length > 1) {
    const previous = levels.at(-1);
    const next = [];
    for (let index = 0; index < previous.length; index += 2) {
      if (index + 1 === previous.length) next.push(previous[index]);
      else { next.push(merkleNodeHash(previous[index], previous[index + 1])); nodeHashCount += 1; }
    }
    levels.push(next);
  }
  if (nodeHashCount >= leaves.length) fail("node_hash_bound_broken");
  return { levels, nodeHashCount };
}

function proofFromLevels(levels, slotIndex) {
  const proof = [];
  let position = slotIndex;
  for (let levelIndex = 0; levelIndex < levels.length - 1; levelIndex += 1) {
    const level = levels[levelIndex];
    const sibling = position ^ 1;
    if (sibling < level.length) proof.push(level[sibling]);
    position = Math.floor(position / 2);
  }
  if (proof.length > FOUNDER_PROOF_CEILING_V02) fail("proof_depth_exceeded");
  return proof;
}

function abiEncodeLeaf({ campaignId, cohortId, slotIndex, memberCount, npubRaw32, wallet }) {
  return concatBytes(
    wordFromBigInt(1),
    wordFromBytes32(CHAIN_DOMAIN),
    wordFromBytes32(campaignId),
    wordFromBigInt(cohortId),
    wordFromBigInt(slotIndex),
    wordFromBigInt(memberCount),
    wordFromBytes32(npubRaw32),
    wordFromAddress(wallet),
  );
}

export function compileFounderProofsV02({ state, commitment, includeAllProofs = false } = {}) {
  const { capacity, founders } = validate(state, commitment);
  const leaves = founders.map((item, slotIndex) => robinhoodLeafHash({
    campaignId: commitment.campaignId, cohortId: 0, slotIndex,
    memberCount: capacity, npubRaw32: `0x${decodeNpub(item.npub).pubkeyHex}`, wallet: item.wallet,
  }));
  const { levels, nodeHashCount } = buildLevels(leaves);
  const root = levels.at(-1)[0];
  const manifest = {
    schema: "bermlaunch.prelaunch_manifest.v02", campaignId: commitment.campaignId,
    commitmentHash: state.commitmentHash, compilerHash: commitment.compilerHash,
    capacity, acceptedCount: founders.length, closeAt: commitment.closeAt,
    closeReason: state.closed.closeReason, cutoff: state.closed.cutoff,
    members: founders.map((item) => ({ slotIndex: item.slotIndex, npub: item.npub,
      wallet: item.wallet, recordRef: item.recordRef, evidenceHash: item.evidenceHash })),
    prelaunchRoot: root,
  };
  const evidenceManifestHash = keccak256Hex(utf8Bytes(jcsCanonicalize(manifest)));
  const counters = Object.freeze({ acceptedCount: founders.length, treeLevels: levels.length,
    nodeHashCount, proofExtractionNodeHashes: 0, maxProofDepth: levels.length - 1 });
  function lookup({ slotIndex, npub }) {
    if (!Number.isSafeInteger(slotIndex) || slotIndex < 0 || slotIndex >= founders.length
        || founders[slotIndex].npub !== npub) fail("lookup_mismatch");
    const item = founders[slotIndex];
    return Object.freeze({ slotIndex, npub, wallet: item.wallet,
      recordRef: item.recordRef, evidenceHash: item.evidenceHash,
      leaf: leaves[slotIndex], proof: proofFromLevels(levels, slotIndex) });
  }
  if (!includeAllProofs) return Object.freeze({ root, manifest, evidenceManifestHash, leaves, counters, lookup });
  const records = founders.map((item, slotIndex) => lookup({ slotIndex, npub: item.npub }));
  const maxProofDepth = Math.max(...records.map((record) => record.proof.length));
  if (maxProofDepth > FOUNDER_PROOF_CEILING_V02) fail("proof_depth_exceeded");
  const content = {
    schema: FOUNDER_PROOF_BUNDLE_SCHEMA_V02, proofVersion: 2,
    proofCeiling: FOUNDER_PROOF_CEILING_V02,
    campaignId: commitment.campaignId, commitmentHash: state.commitmentHash,
    compilerHash: commitment.compilerHash, capacity, acceptedCount: founders.length,
    prelaunchRoot: root, evidenceManifestHash, records,
  };
  const bytes = Buffer.from(jcsCanonicalize(content), "utf8");
  const contentHash = `sha256:${createHash("sha256").update(bytes).digest("hex")}`;
  const bundle = Object.freeze({ ...content, contentHash });
  return Object.freeze({ root, manifest, evidenceManifestHash, leaves, counters: Object.freeze({ ...counters, maxProofDepth }),
    bundle, bundleBytes: Buffer.byteLength(jcsCanonicalize(bundle)), lookup });
}

export function verifyFounderProofBundleV02(bundle) {
  if (bundle?.schema !== FOUNDER_PROOF_BUNDLE_SCHEMA_V02 || !Array.isArray(bundle.records)
      || bundle.records.length !== bundle.acceptedCount || bundle.proofCeiling !== FOUNDER_PROOF_CEILING_V02) {
    fail("bundle_shape_invalid");
  }
  const { contentHash, ...content } = bundle;
  if (`sha256:${createHash("sha256").update(jcsCanonicalize(content)).digest("hex")}` !== contentHash) {
    fail("bundle_hash_invalid");
  }
  for (let index = 0; index < bundle.records.length; index += 1) {
    const record = bundle.records[index];
    if (record.slotIndex !== index || record.proof.length > FOUNDER_PROOF_CEILING_V02
        || record.leaf !== robinhoodLeafHash({ campaignId: bundle.campaignId, cohortId: 0,
          slotIndex: index, memberCount: bundle.capacity,
          npubRaw32: `0x${decodeNpub(record.npub).pubkeyHex}`, wallet: record.wallet })
        || !verifyMerkleProof({ leaf: record.leaf, proof: record.proof, root: bundle.prelaunchRoot })) {
      fail(`record_invalid:${index}`);
    }
  }
  return Object.freeze({ verified: bundle.records.length, contentHash, maxProofDepth: Math.max(...bundle.records.map((r) => r.proof.length)) });
}

export function jcsCanonicalize(value) {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "string") {
    if (hasLoneSurrogate(value)) throw new Error("jcs_lone_surrogate");
    return JSON.stringify(value);
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new Error("jcs_non_finite_number");
    if (!Number.isInteger(value)) throw new Error("jcs_non_integer_number");
    if (Object.is(value, -0)) throw new Error("jcs_negative_zero");
    if (!Number.isSafeInteger(value)) throw new Error("jcs_unsafe_integer");
    return String(value);
  }
  if (Array.isArray(value)) return `[${value.map(jcsCanonicalize).join(",")}]`;
  if (value && typeof value === "object") {
    const keys = Object.keys(value);
    for (const key of keys) if (hasLoneSurrogate(key)) throw new Error("jcs_lone_surrogate");
    return `{${keys.sort().map((key) => `${JSON.stringify(key)}:${jcsCanonicalize(value[key])}`).join(",")}}`;
  }
  throw new Error(`jcs_unsupported_type:${typeof value}`);
}

function claimBuyback(
    uint8 cohortId,
    uint32 slotIndex,
    bytes32 npubRaw,
    address wallet,
    bytes32[] calldata proof,
    uint256 minTokensOut,
    uint256 deadline
) external nonReentrant returns (uint256 tokensReceived) {
    if (!launchBound) revert LaunchNotBound();
    if (cohortId != PRELAUNCH && !graduatedActive) revert NotGraduated();
    if (msg.sender != wallet) revert Unauthorized();
    if (block.timestamp > deadline) revert DeadlineExpired();
    if (minTokensOut == 0) revert InvalidConfiguration();
    uint32 count = memberCount(cohortId);
    if (slotIndex >= count) revert InvalidCohort();
    if (cohortId == PRELAUNCH) {
        if (npubRaw == bytes32(0) || wallet == address(0)) revert InvalidConfiguration();
        if (slotIndex >= founderFilled || proof.length > MAX_PROOF_LENGTH) revert InvalidProof();
        bytes32 leaf = leafHash(cohortId, slotIndex, count, npubRaw, wallet);
        if (!_verifyProof(leaf, proof, cohortRoots[PRELAUNCH])) revert InvalidProof();
    } else {
        if (proof.length != 0) revert InvalidProof();
        Assignment storage a = assignments[cohortId][slotIndex];
        if (a.npubRaw != npubRaw || a.wallet != wallet || a.evidenceHash == bytes32(0)) revert AssignmentMismatch();
    }

    bytes32 identityHash = keccak256(abi.encode(campaignId, npubRaw));
    ClaimState storage cs = claimStates[identityHash];
    if (cohortId == PRELAUNCH && !cs.initialized) {
        if (identityAssigned[identityHash]) revert IdentityCollision();
        identityAssigned[identityHash] = true;
        cs.initialized = true;
        cs.cohortId = PRELAUNCH;
        cs.slotIndex = slotIndex;
        cs.wallet = wallet;
    } else if (!cs.initialized || cs.cohortId != cohortId || cs.slotIndex != slotIndex || cs.wallet != wallet) {
        revert IdentityCollision();
    }

    uint256 entitlement = slotEntitlement(totalReceived, cohortId, slotIndex);
    if (cs.grossSpent > entitlement) revert AccountingDeficit();
    uint256 grossAvailable = entitlement - cs.grossSpent;
    if (grossAvailable == 0) revert NothingToClaim();
    if (grossAvailable < minimumClaimGross) revert BelowMinimumClaim();

    uint256 fee = _mulDiv(grossAvailable, operatingFeeBps, BPS);
    uint256 swapInput = grossAvailable - fee;
    if (swapInput == 0) revert BelowMinimumClaim();

    // Effects first. Revert semantics restore state if any external call fails.
    cs.grossSpent += grossAvailable;
    totalUserGrossSpent += grossAvailable;

    if (fee != 0) _safeTransfer(weth, operatingFeeRecipient, fee);

    uint256 beforeTokens = IERC20Minimal(token).balanceOf(wallet);
    _forceApprove(weth, swapAdapter, swapInput);
    uint256 adapterReported =
        IBermSwapAdapter(swapAdapter).swapExactIn(weth, token, poolId, swapInput, minTokensOut, wallet, deadline);
    _forceApprove(weth, swapAdapter, 0);
    uint256 afterTokens = IERC20Minimal(token).balanceOf(wallet);
    if (afterTokens < beforeTokens) revert AccountingDeficit();
    tokensReceived = afterTokens - beforeTokens;
    if (tokensReceived < minTokensOut || adapterReported < minTokensOut) revert SlippageExceeded();

    emit PocketConverted(identityHash, cohortId, slotIndex, wallet, grossAvailable, fee, swapInput, tokensReceived);
}

function availableFounderPocket(uint32 slotIndex, bytes32 npubRaw, address wallet, bytes32[] calldata proof)
    external view returns (uint256)
{
    if (npubRaw == bytes32(0) || wallet == address(0)) revert InvalidConfiguration();
    if (slotIndex >= founderFilled || proof.length > MAX_PROOF_LENGTH) revert InvalidProof();
    bytes32 leaf = leafHash(PRELAUNCH, slotIndex, prelaunchCapacity, npubRaw, wallet);
    if (!_verifyProof(leaf, proof, cohortRoots[PRELAUNCH])) revert InvalidProof();
    bytes32 identityHash = keccak256(abi.encode(campaignId, npubRaw));
    ClaimState storage member = claimStates[identityHash];
    if (member.initialized) {
        if (member.cohortId != PRELAUNCH || member.slotIndex != slotIndex || member.wallet != wallet) {
            revert IdentityCollision();
        }
    } else if (identityAssigned[identityHash]) revert IdentityCollision();
    uint256 entitlement = slotEntitlement(totalReceived, PRELAUNCH, slotIndex);
    if (member.grossSpent > entitlement) revert AccountingDeficit();
    return entitlement - member.grossSpent;
}

function availablePocket(bytes32 npubRaw, uint8 cohortId, uint32 slotIndex) external view returns (uint256) {
    bytes32 identityHash = keccak256(abi.encode(campaignId, npubRaw));
    ClaimState storage member = claimStates[identityHash];
    if (!member.initialized || member.cohortId != cohortId || member.slotIndex != slotIndex) {
        revert IdentityCollision();
    }
    uint256 entitlement = slotEntitlement(totalReceived, cohortId, slotIndex);
    uint256 spent = member.grossSpent;
    if (spent > entitlement) revert AccountingDeficit();
    return entitlement - spent;
}

function swapExactIn(address inputToken, address outputToken, bytes32 suppliedPoolId,
    uint256 amountIn, uint256 minAmountOut, address recipient, uint256 deadline) external returns (uint256 amountOut) {
    if (_lock != 1) revert ReentrantCall();
    _lock = 2;
    if (block.timestamp > deadline) revert DeadlineExpired();
    if (recipient == address(0) || amountIn == 0 || minAmountOut == 0) revert InvalidRoute();
    if (inputToken != weth || outputToken == weth || suppliedPoolId != computePoolId(outputToken)) revert InvalidRoute();
    if (amountIn > type(uint128).max || amountIn > type(uint160).max || minAmountOut > type(uint128).max
        || deadline > type(uint48).max) revert AmountTooLarge();
    IBagsLens.TokenState memory state = _routeState(outputToken, suppliedPoolId);
    if (state.migrated) amountOut = _swapV4(inputToken, outputToken, amountIn, minAmountOut, recipient, deadline);
    else amountOut = _swapCurve(state.curve, outputToken, amountIn, minAmountOut, recipient);
    _lock = 1;
}

function _routeState(address outputToken, bytes32 suppliedPoolId) internal view returns (IBagsLens.TokenState memory state) {
    if (weth.codehash != wethCodeHash || bagsLens.codehash != lensCodeHash || bagsFactory.codehash != factoryCodeHash
        || hook.codehash != hookCodeHash || universalRouter.codehash != routerCodeHash || permit2.codehash != permit2CodeHash
        || curveBeacon.codehash != curveBeaconCodeHash || curveImplementation.codehash != curveImplementationCodeHash
        || IBagsLens(bagsLens).FACTORY() != bagsFactory
        || IBagsDualPhaseFactory(bagsFactory).bondingCurveBeacon() != curveBeacon
        || IBagsDualPhaseBeacon(curveBeacon).implementation() != curveImplementation) revert ProviderIdentityChanged();
    state = IBagsLens(bagsLens).getTokenState(outputToken);
    if (!state.exists || state.curve == address(0) || state.poolId != suppliedPoolId
        || IBagsDualPhaseFactory(bagsFactory).curveForToken(outputToken) != state.curve
        || state.curve.codehash != curveProxyCodeHash) revert InvalidRoute();
    IBagsDualPhaseCurve curve = IBagsDualPhaseCurve(state.curve);
    if (curve.TOKEN() != outputToken || curve.WETH() != weth || curve.migrated() != state.migrated) revert InvalidRoute();
}

function _swapCurve(address curveAddress, address outputToken, uint256 amountIn,
    uint256 minAmountOut, address recipient) internal returns (uint256 amountOut) {
    IBagsDualPhaseCurve curve = IBagsDualPhaseCurve(curveAddress);
    if (curve.paused()) revert CurvePaused();
    (uint256 quotedOut,,, uint256 grossUsed, uint256 refundQuote) = curve.quoteBuy(amountIn);
    if (grossUsed != amountIn || refundQuote != 0) revert PartialInputRefused();
    if (quotedOut < minAmountOut) revert SlippageExceeded();
    uint256 wethBefore = IERC20Minimal(weth).balanceOf(address(this));
    uint256 nativeBefore = address(this).balance;
    uint256 tokenBefore = IERC20Minimal(outputToken).balanceOf(recipient);
    _safeTransferFrom(weth, msg.sender, address(this), amountIn);
    if (IERC20Minimal(weth).balanceOf(address(this)) != wethBefore + amountIn) revert InputNotFullyConsumed();
    IWethDualPhase(weth).withdraw(amountIn);
    if (IERC20Minimal(weth).balanceOf(address(this)) != wethBefore || address(this).balance != nativeBefore + amountIn)
        revert InputNotFullyConsumed();
    curve.buyFor{value: amountIn}(recipient, minAmountOut);
    if (address(this).balance != nativeBefore || IERC20Minimal(weth).balanceOf(address(this)) != wethBefore)
        revert InputNotFullyConsumed();
    uint256 tokenAfter = IERC20Minimal(outputToken).balanceOf(recipient);
    if (tokenAfter < tokenBefore) revert TokenOperationFailed();
    amountOut = tokenAfter - tokenBefore;
    if (amountOut < minAmountOut) revert SlippageExceeded();
}

function _swapV4(address inputToken, address outputToken, uint256 amountIn,
    uint256 minAmountOut, address recipient, uint256 deadline) internal returns (uint256 amountOut) {
    PoolKey memory key = poolKeyFor(outputToken);
    bool zeroForOne = key.currency0 == weth;
    SwapExactInSingle memory swapParams = SwapExactInSingle({poolKey: key, zeroForOne: zeroForOne,
        amountIn: uint128(amountIn), amountOutMinimum: uint128(minAmountOut), minHopPriceX36: 0, hookData: bytes("")});
    uint256 inputBefore = IERC20Minimal(inputToken).balanceOf(address(this));
    uint256 outputBefore = IERC20Minimal(outputToken).balanceOf(address(this));
    _safeTransferFrom(inputToken, msg.sender, address(this), amountIn);
    _forceApprove(inputToken, permit2, amountIn);
    IPermit2Minimal(permit2).approve(inputToken, universalRouter, uint160(amountIn), uint48(deadline));
    bytes memory actions = abi.encodePacked(SWAP_EXACT_IN_SINGLE, SETTLE_ALL, TAKE_ALL);
    bytes[] memory actionInputs = new bytes[](3);
    actionInputs[0] = abi.encode(swapParams);
    actionInputs[1] = abi.encode(inputToken, amountIn);
    actionInputs[2] = abi.encode(outputToken, minAmountOut);
    bytes[] memory routerInputs = new bytes[](1);
    routerInputs[0] = abi.encode(actions, actionInputs);
    IUniversalRouterModified(universalRouter).execute(abi.encodePacked(V4_SWAP), routerInputs, deadline);
    IPermit2Minimal(permit2).approve(inputToken, universalRouter, 0, 0);
    _forceApprove(inputToken, permit2, 0);
    uint256 inputAfter = IERC20Minimal(inputToken).balanceOf(address(this));
    if (inputAfter != inputBefore) revert InputNotFullyConsumed();
    uint256 outputAfter = IERC20Minimal(outputToken).balanceOf(address(this));
    if (outputAfter < outputBefore) revert TokenOperationFailed();
    amountOut = outputAfter - outputBefore;
    if (amountOut < minAmountOut) revert SlippageExceeded();
    _safeTransfer(outputToken, recipient, amountOut);
}

function poolKeyFor(address bagsToken) public view returns (PoolKey memory key) {
    if (bagsToken == address(0) || bagsToken == weth) revert InvalidRoute();
    if (uint160(bagsToken) < uint160(weth)) key = PoolKey(bagsToken, weth, DYNAMIC_FEE_FLAG, TICK_SPACING, hook);
    else key = PoolKey(weth, bagsToken, DYNAMIC_FEE_FLAG, TICK_SPACING, hook);
}

constructor(address weth_, address bagsLens_, address hook_, address universalRouter_,
    address permit2_, bytes32 curveProxyCodeHash_) {
    if (block.chainid != ROBINHOOD_CHAIN_ID) revert WrongChain();
    if (weth_.code.length == 0 || bagsLens_.code.length == 0 || hook_.code.length == 0
        || universalRouter_.code.length == 0 || permit2_.code.length == 0
        || curveProxyCodeHash_ == bytes32(0)) revert InvalidAddress();
    address factory = IBagsLens(bagsLens_).FACTORY();
    if (factory.code.length == 0 || IBagsDualPhaseFactory(factory).weth() != weth_
        || IBagsDualPhaseFactory(factory).hook() != hook_) revert InvalidRoute();
    address beacon = IBagsDualPhaseFactory(factory).bondingCurveBeacon();
    if (beacon.code.length == 0) revert InvalidAddress();
    address implementation = IBagsDualPhaseBeacon(beacon).implementation();
    if (implementation.code.length == 0) revert InvalidAddress();
    weth = weth_; bagsLens = bagsLens_; bagsFactory = factory; hook = hook_;
    universalRouter = universalRouter_; permit2 = permit2_;
    curveBeacon = beacon; curveImplementation = implementation;
    curveProxyCodeHash = curveProxyCodeHash_;
    wethCodeHash = weth_.codehash; lensCodeHash = bagsLens_.codehash;
    factoryCodeHash = factory.codehash; hookCodeHash = hook_.codehash;
    routerCodeHash = universalRouter_.codehash; permit2CodeHash = permit2_.codehash;
    curveBeaconCodeHash = beacon.codehash; curveImplementationCodeHash = implementation.codehash;
}

function _communityBpsForPreset(uint8 preset) internal pure returns (uint16) {
    if (preset == PRESET_COMMUNITY_FIRST) return 7_500;
    if (preset == PRESET_BERM_STANDARD) return 6_000;
    if (preset == PRESET_BALANCED) return 5_000;
    revert InvalidEconomicPreset();
}

function _cumulativeCohortBps(uint16 selectedCommunityBps, uint8 cohortBoundary) internal pure returns (uint16) {
    return uint16(_mulDiv(selectedCommunityBps, cohortBoundary, COHORT_COUNT));
}

function rangeAllocation(uint256 total, uint256 start, uint256 end, uint256 denominator)
    public
    pure
    returns (uint256)
{
    if (denominator == 0 || start > end || end > denominator) revert InvalidConfiguration();
    return _mulDiv(total, end, denominator) - _mulDiv(total, start, denominator);
}

function _mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) {
    unchecked {
        uint256 prod0;
        uint256 prod1;
        assembly ("memory-safe") {
            let mm := mulmod(x, y, not(0))
            prod0 := mul(x, y)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }
        if (prod1 == 0) return prod0 / denominator;
        if (denominator <= prod1) revert InvalidConfiguration();

        uint256 remainder;
        assembly ("memory-safe") { remainder := mulmod(x, y, denominator) }
        assembly ("memory-safe") {
            prod1 := sub(prod1, gt(remainder, prod0))
            prod0 := sub(prod0, remainder)
        }
        uint256 twos = denominator & (~denominator + 1);
        assembly ("memory-safe") { denominator := div(denominator, twos) }
        assembly ("memory-safe") { prod0 := div(prod0, twos) }
        assembly ("memory-safe") { twos := add(div(sub(0, twos), twos), 1) }
        prod0 |= prod1 * twos;

        uint256 inverse = (3 * denominator) ^ 2;
        inverse *= 2 - denominator * inverse;
        inverse *= 2 - denominator * inverse;
        inverse *= 2 - denominator * inverse;
        inverse *= 2 - denominator * inverse;
        inverse *= 2 - denominator * inverse;
        inverse *= 2 - denominator * inverse;
        result = prod0 * inverse;
        return result;
    }
}

function memberCount(uint8 cohortId) public view returns (uint32) {
    if (cohortId == PRELAUNCH) return prelaunchCapacity;
    if (cohortId == GRADUATION) return graduationCapacity;
    if (cohortId == FOMO) return fomoCapacity;
    revert InvalidCohort();
}

function slotEntitlement(uint256 received, uint8 cohortId, uint32 slotIndex) public view returns (uint256) {
    uint32 count = memberCount(cohortId);
    if (slotIndex >= count) revert InvalidCohort();
    return rangeAllocation(cohortTotal(received, cohortId), slotIndex, slotIndex + 1, count);
}

function creatorTotal(uint256 received) public view returns (uint256) {
    return rangeAllocation(received, communityBps, BPS, BPS);
}

function claimResidual() external nonReentrant returns (uint256 amount) {
    uint256 entitled = creatorTotal(totalReceived);
    if (residualSpent > entitled) revert AccountingDeficit();
    amount = entitled - residualSpent;
    if (amount == 0) revert NothingToClaim();
    residualSpent = entitled;
    _safeTransfer(weth, residualRecipient, amount);
    emit ResidualClaimed(amount, residualSpent);
}

function unusedAvailable(uint8 cohortId) public view returns (uint256) {
    uint32 filled;
    uint32 capacity;
    uint256 spent;
    if (cohortId == PRELAUNCH) {
        filled = founderFilled;
        capacity = prelaunchCapacity;
        spent = unusedGrossSpent[0];
    } else if (cohortId == GRADUATION) {
        if (!graduationClosed) revert CohortNotOpen();
        filled = graduationFilled;
        capacity = graduationCapacity;
        spent = unusedGrossSpent[1];
    } else revert InvalidCohort();
    if (filled == capacity) return 0;
    uint256 gross = rangeAllocation(cohortTotal(totalReceived, cohortId), filled, capacity, capacity);
    if (spent > gross) revert AccountingDeficit();
    return gross - spent;
}

function convertUnusedTail(uint8 cohortId, uint256 minTokensOut, uint256 deadline)
    external nonReentrant returns (uint256 tokensReceived)
{
    if (!graduatedActive) revert NotGraduated();
    if (cohortId != PRELAUNCH && cohortId != GRADUATION) revert InvalidCohort();
    if (block.timestamp > deadline) revert DeadlineExpired();
    if (minTokensOut == 0) revert InvalidConfiguration();
    uint256 grossAvailable = unusedAvailable(cohortId);
    if (grossAvailable == 0) revert NoUnusedTail();
    uint256 fee = _mulDiv(grossAvailable, operatingFeeBps, BPS);
    uint256 swapInput = grossAvailable - fee;
    if (swapInput == 0) revert BelowMinimumClaim();
    unusedGrossSpent[cohortId] += grossAvailable;
    totalUnusedGrossSpent += grossAvailable;
    if (fee != 0) _safeTransfer(weth, operatingFeeRecipient, fee);
    uint256 beforeTokens = IERC20Minimal(token).balanceOf(UNUSED_TOKEN_SINK);
    _forceApprove(weth, swapAdapter, swapInput);
    uint256 adapterReported = IBermSwapAdapter(swapAdapter).swapExactIn(
        weth, token, poolId, swapInput, minTokensOut, UNUSED_TOKEN_SINK, deadline
    );
    _forceApprove(weth, swapAdapter, 0);
    uint256 afterTokens = IERC20Minimal(token).balanceOf(UNUSED_TOKEN_SINK);
    if (afterTokens < beforeTokens) revert AccountingDeficit();
    tokensReceived = afterTokens - beforeTokens;
    if (tokensReceived < minTokensOut || adapterReported < minTokensOut) revert SlippageExceeded();
    emit UnusedTailConverted(
        cohortId,
        cohortId == PRELAUNCH ? founderFilled : graduationFilled,
        memberCount(cohortId), grossAvailable, fee, swapInput, tokensReceived, UNUSED_TOKEN_SINK
    );
}

function expectedFeeAssetBalance() public view returns (uint256) {
    uint256 consumed = totalUserGrossSpent + totalUnusedGrossSpent + residualSpent;
    if (consumed > totalReceived) revert AccountingDeficit();
    return totalReceived - consumed;
}

function bindLaunch(address token_, address feeShare_) external {
    if (msg.sender != launchBinder) revert Unauthorized();
    if (launchBound) revert AlreadyBound();
    if (token_ == address(0) || feeShare_ == address(0)) revert ZeroAddress();

    if (IBagsLens(bagsLens).FACTORY() != bagsFactory) revert InvalidLaunchBinding();
    IBagsLens.TokenState memory state = IBagsLens(bagsLens).getTokenState(token_);
    IBagsFeeShare fs = IBagsFeeShare(feeShare_);
    (address[] memory claimers, uint16[] memory bps) = fs.getClaimers();
    BagsAuthoritySnapshot memory snapshot = _resolveBagsAuthority(fs);
    bool acceptedFeeShareOwner = snapshot.feeShareOwner == address(0)
        || (snapshot.feeShareOwner == snapshot.factoryOwner);

    if (
        !state.exists || state.feeShare != feeShare_ || state.curve == address(0) || state.poolId == bytes32(0)
            || claimers.length != 1 || bps.length != 1 || claimers[0] != address(this) || bps[0] != 10_000
            || !acceptedFeeShareOwner || snapshot.feeShareBeacon == address(0)
            || snapshot.feeShareImplementation == address(0) || _hasAuthorityCollision(snapshot)
            || fs.WETH() != weth || fs.hook() != expectedHook
            || fs.poolId() != state.poolId || fs.bondingCurve() != state.curve
            || !_adapterSupports(weth, token_, state.poolId)
    ) revert InvalidLaunchBinding();

    bagsAuthoritySnapshot = snapshot;
    token = token_;
    feeShare = feeShare_;
    bondingCurve = state.curve;
    poolId = state.poolId;
    launchBound = true;
    emit LaunchBound(token_, feeShare_, state.curve, state.poolId);
}

function harvest() external nonReentrant returns (uint256 amount) {
    if (!launchBound) revert LaunchNotBound();
    uint256 beforeBalance = IERC20Minimal(weth).balanceOf(address(this));
    IBagsFeeShare(feeShare).claim(false);
    uint256 afterBalance = IERC20Minimal(weth).balanceOf(address(this));
    if (afterBalance <= beforeBalance) revert NoFeesHarvested();
    amount = afterBalance - beforeBalance;
    totalReceived += amount;
    emit FeesHarvested(amount, totalReceived);
}

function syncExternalDeposit() external returns (uint256 amount) {
    uint256 expected = expectedFeeAssetBalance();
    uint256 actual = IERC20Minimal(weth).balanceOf(address(this));
    if (actual < expected) revert AccountingDeficit();
    amount = actual - expected;
    if (amount != 0) {
        totalReceived += amount;
        emit ExternalDepositSynchronized(amount, totalReceived);
    }
}

function finalizeGraduation(uint32 expectedFilled, bytes32 closeEvidenceHash) external {
    if (msg.sender != configuredRootFinalizer) revert Unauthorized();
    if (!launchBound) revert LaunchNotBound();
    if (graduatedActive) revert CohortClosed();
    if (closeEvidenceHash == bytes32(0)) revert InvalidConfiguration();
    if (expectedFilled != graduationFilled) revert GraduationFillMismatch();
    IBagsLens.TokenState memory state = IBagsLens(bagsLens).getTokenState(token);
    if (
        !state.exists || !state.migrated || state.curve != bondingCurve || state.feeShare != feeShare
            || state.poolId != poolId
    ) revert NotGraduated();
    graduatedActive = true;
    if (!graduationClosed) {
        graduationClosed = true;
        emit GraduationCohortClosed(graduationFilled, graduationCapacity, true);
    }
    emit GraduationCutoffFinalized(graduationFilled, closeEvidenceHash);
    emit GraduationActivated(token, poolId);
}

function claimBuyback(
    uint8 cohortId,
    uint32 slotIndex,
    bytes32 npubRaw,
    address wallet,
    bytes32[] calldata proof,
    uint256 minTokensOut,
    uint256 deadline
) external nonReentrant returns (uint256 tokensReceived) {
    if (!launchBound) revert LaunchNotBound();
    if (cohortId != PRELAUNCH && !graduatedActive) revert NotGraduated();
    if (msg.sender != wallet) revert Unauthorized();
    if (block.timestamp > deadline) revert DeadlineExpired();
    if (minTokensOut == 0) revert InvalidConfiguration();
    uint32 count = memberCount(cohortId);
    if (slotIndex >= count) revert InvalidCohort();
    if (cohortId == PRELAUNCH) {
        if (npubRaw == bytes32(0) || wallet == address(0)) revert InvalidConfiguration();
        if (slotIndex >= founderFilled || proof.length > MAX_PROOF_LENGTH) revert InvalidProof();
        bytes32 leaf = leafHash(cohortId, slotIndex, count, npubRaw, wallet);
        if (!_verifyProof(leaf, proof, cohortRoots[PRELAUNCH])) revert InvalidProof();
    } else {
        if (proof.length != 0) revert InvalidProof();
        Assignment storage a = assignments[cohortId][slotIndex];
        if (a.npubRaw != npubRaw || a.wallet != wallet || a.evidenceHash == bytes32(0)) revert AssignmentMismatch();
    }

    bytes32 identityHash = keccak256(abi.encode(campaignId, npubRaw));
    ClaimState storage cs = claimStates[identityHash];
    if (cohortId == PRELAUNCH && !cs.initialized) {
        if (identityAssigned[identityHash]) revert IdentityCollision();
        identityAssigned[identityHash] = true;
        cs.initialized = true;
        cs.cohortId = PRELAUNCH;
        cs.slotIndex = slotIndex;
        cs.wallet = wallet;
    } else if (!cs.initialized || cs.cohortId != cohortId || cs.slotIndex != slotIndex || cs.wallet != wallet) {
        revert IdentityCollision();
    }

    uint256 entitlement = slotEntitlement(totalReceived, cohortId, slotIndex);
    if (cs.grossSpent > entitlement) revert AccountingDeficit();
    uint256 grossAvailable = entitlement - cs.grossSpent;
    if (grossAvailable == 0) revert NothingToClaim();
    if (grossAvailable < minimumClaimGross) revert BelowMinimumClaim();

    uint256 fee = _mulDiv(grossAvailable, operatingFeeBps, BPS);
    uint256 swapInput = grossAvailable - fee;
    if (swapInput == 0) revert BelowMinimumClaim();

    // Effects first. Revert semantics restore state if any external call fails.
    cs.grossSpent += grossAvailable;
    totalUserGrossSpent += grossAvailable;

    if (fee != 0) _safeTransfer(weth, operatingFeeRecipient, fee);

    uint256 beforeTokens = IERC20Minimal(token).balanceOf(wallet);
    _forceApprove(weth, swapAdapter, swapInput);
    uint256 adapterReported =
        IBermSwapAdapter(swapAdapter).swapExactIn(weth, token, poolId, swapInput, minTokensOut, wallet, deadline);
    _forceApprove(weth, swapAdapter, 0);
    uint256 afterTokens = IERC20Minimal(token).balanceOf(wallet);
    if (afterTokens < beforeTokens) revert AccountingDeficit();
    tokensReceived = afterTokens - beforeTokens;
    if (tokensReceived < minTokensOut || adapterReported < minTokensOut) revert SlippageExceeded();

    emit PocketConverted(identityHash, cohortId, slotIndex, wallet, grossAvailable, fee, swapInput, tokensReceived);
}

    const publication = await publishCampaignSurvivabilityV02({ built: persisted,
      publisher: survivability.publisher, readback: survivability.readback,
      configuredRelays: survivability.configuredRelays });
    frozenEvent.recoveryPackageHash = persisted.packageHash;
    frozenEvent.recoveryPackageBytes = persisted.packageBytes.length;
    frozenEvent.survivabilityPublication = publication;
    await append(await readJournal(), frozenEvent);
    frozenArtifact = artifact;
    recoveryArtifact = persisted;
    return Object.freeze({ compiled, verified });
  } finally {
    await release();
  }
}

export function buildCampaignSurvivabilityPackageV02({ manifest, proofBundle, lawBytes, lawSha256,
  closeReceipt, closeSignature, chainId, factoryAddress } = {}) {
  if (!SHA.test(lawSha256 ?? "") || survivabilitySha256(lawBytes) !== lawSha256) fail("law_hash_mismatch");
  const law = exactJson(lawBytes, "law");
  if (!manifest || manifest.schema !== "bermlaunch.prelaunch_manifest.v02"
      || !proofBundle || !closeReceipt || typeof closeSignature !== "string"
      || !Number.isSafeInteger(chainId) || chainId < 1
      || !/^0x[0-9a-fA-F]{40}$/.test(factoryAddress ?? "")) fail("inputs_invalid");
  verifyFounderProofBundleV02(proofBundle);
  const manifestBytes = canonicalBytes(manifest);
  const proofBundleBytes = canonicalBytes(proofBundle);
  const evidenceManifestHash = keccak256Hex(utf8Bytes(manifestBytes.toString("utf8")));
  if (manifest.campaignId !== proofBundle.campaignId
      || manifest.commitmentHash !== proofBundle.commitmentHash
      || manifest.prelaunchRoot !== proofBundle.prelaunchRoot
      || manifest.acceptedCount !== proofBundle.acceptedCount
      || manifest.capacity !== proofBundle.capacity
      || proofBundle.evidenceManifestHash !== evidenceManifestHash
      || closeReceipt.campaignId !== manifest.campaignId
      || closeReceipt.commitmentHash !== manifest.commitmentHash
      || closeReceipt.prelaunchRoot !== manifest.prelaunchRoot
      || closeReceipt.evidenceManifestHash !== evidenceManifestHash) fail("cross_binding_invalid");
  const index = {
    schema: "bermlaunch.survivability_recovery_index.v1", chainId, factoryAddress,
    campaignId: manifest.campaignId, commitmentHash: manifest.commitmentHash,
    prelaunchRoot: manifest.prelaunchRoot, evidenceManifestHash,
    acceptedCount: manifest.acceptedCount, capacity: manifest.capacity,
    manifest: { sha256: survivabilitySha256(manifestBytes), bytes: manifestBytes.length },
    proofBundle: { sha256: survivabilitySha256(proofBundleBytes), bytes: proofBundleBytes.length,
      contentHash: proofBundle.contentHash },
    law: { sha256: lawSha256, bytes: lawBytes.length },
  };
  const packageValue = {
    schema: "bermlaunch.survivability_package.v1", index, manifest, proofBundle, law,
    closeReceipt, closeSignature,
  };
  const indexBytes = canonicalBytes(index);
  const packageBytes = canonicalBytes(packageValue);
  return Object.freeze({ manifestBytes, proofBundleBytes, indexBytes, lawBytes: Buffer.from(lawBytes),
    packageBytes, index, packageHash: survivabilitySha256(packageBytes) });
}

export async function publishCampaignSurvivabilityV02({ built, publisher, readback, configuredRelays } = {}) {
  if (!built?.packageBytes || !SHA.test(built.packageHash ?? "")
      || typeof publisher?.publishDurable !== "function"
      || typeof publisher?.publishNostrPointer !== "function"
      || typeof readback?.readDurable !== "function"
      || typeof readback?.confirmPersistence !== "function"
      || typeof readback?.readNostrPointer !== "function"
      || publisher === readback) fail("boundaries_unavailable");
  const requiredRelays = Array.isArray(configuredRelays) ? [...new Set(configuredRelays)] : [];
  if (requiredRelays.length < 2 || requiredRelays.some((relay) => !nonlocalRelay(relay))) {
    fail("nostr_relay_policy_invalid");
  }
  const durable = await publisher.publishDurable(Buffer.from(built.packageBytes));
  if (!["ARWEAVE", "IPFS_PERSISTENT"].includes(durable?.class)
      || typeof durable.locator !== "string" || !durable.locator
      || durable.persistenceConfirmed !== true
      || durable.sha256 !== built.packageHash || durable.bytes !== built.packageBytes.length) {
    fail("durable_policy_invalid");
  }
  exactBytes(await readback.readDurable(durable.locator), built.packageBytes, "durable_readback_mismatch");
  if (await readback.confirmPersistence(durable.locator, durable.class) !== true) {
    fail("durable_persistence_unconfirmed");
  }
  const pointer = {
    schema: "bermlaunch.survivability_nostr_pointer.v1",
    campaignId: built.index.campaignId, chainId: built.index.chainId,
    factoryAddress: built.index.factoryAddress,
    packageSha256: built.packageHash, packageBytes: built.packageBytes.length,
    evidenceManifestHash: built.index.evidenceManifestHash,
    lawSha256: built.index.law.sha256,
    durableClass: durable.class, durableLocator: durable.locator,
  };
  if (!HEX32.test(pointer.campaignId) || !HEX32.test(pointer.evidenceManifestHash)) fail("pointer_identity_invalid");
  const pointerBytes = Buffer.from(jcsCanonicalize(pointer), "utf8");
  const announced = await publisher.publishNostrPointer(Buffer.from(pointerBytes));
  if (typeof announced?.eventId !== "string" || !announced.eventId
      || !Array.isArray(announced.relays)) fail("nostr_publication_invalid");
  const announcedRelays = new Set(announced.relays);
  if (requiredRelays.some((relay) => !announcedRelays.has(relay))) fail("nostr_relay_policy_invalid");
  for (const relay of requiredRelays) {
    exactBytes(await readback.readNostrPointer(relay, announced.eventId), pointerBytes, "nostr_readback_mismatch");
  }
  return Object.freeze({ schema: "bermlaunch.survivability_publication_receipt.v1",
    packageSha256: built.packageHash, packageBytes: built.packageBytes.length,
    durableClass: durable.class, durableLocator: durable.locator,
    persistenceConfirmed: true, nostrEventId: announced.eventId,
    relayReadbacks: requiredRelays, pointerSha256: survivabilitySha256(pointerBytes),
    pointerBytes: pointerBytes.length });
}

export async function createCampaignSurvivabilityRuntimeV02({ env = process.env, fetchImpl = globalThis.fetch,
  timeoutMs = 30_000, maxRawBytes = 32 * 1024 * 1024 } = {}) {
  for (const key of REQUIRED) {
    if (typeof env[`BERMLAUNCH_SURVIVABILITY_${key}`] !== "string"
        || !env[`BERMLAUNCH_SURVIVABILITY_${key}`].trim()) fail(`missing_${key.toLowerCase()}`);
  }
  if (typeof fetchImpl !== "function" || !Number.isSafeInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 30_000
      || !Number.isSafeInteger(maxRawBytes) || maxRawBytes < 1 || maxRawBytes > 32 * 1024 * 1024) fail("bounds_invalid");
  const publisherURL = endpoint(env.BERMLAUNCH_SURVIVABILITY_PUBLISHER_URL);
  const readbackURL = endpoint(env.BERMLAUNCH_SURVIVABILITY_READBACK_URL);
  if (publisherURL.href === readbackURL.href) fail("endpoints_not_distinct");
  let configuredRelays;
  try { configuredRelays = relays(JSON.parse(env.BERMLAUNCH_SURVIVABILITY_NOSTR_RELAYS)); }
  catch { fail("relay_set_invalid"); }
  let lawBytes, lawSha256;
  try {
    lawSha256 = (await readFile(hashURL, "utf8")).trim();
    lawBytes = await readFile(env.BERMLAUNCH_SURVIVABILITY_LAW_PATH || lawURL);
  } catch { fail("law_unavailable"); }
  if (!/^sha256:[0-9a-f]{64}$/.test(lawSha256) || sha(lawBytes) !== lawSha256) fail("law_hash_mismatch");
  const publisherToken = await token(env.BERMLAUNCH_SURVIVABILITY_PUBLISHER_TOKEN_FILE);
  const readbackToken = await token(env.BERMLAUNCH_SURVIVABILITY_READBACK_TOKEN_FILE);

  function client(base, bearer) {
    return async (path, { method = "GET", body, json = false } = {}) => {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      let response;
      try {
        const url = new URL(path, base);
        if (url.origin !== base.origin || !url.pathname.startsWith(base.pathname)) fail("origin_refused");
        response = await fetchImpl(url.href, { method, redirect: "manual", credentials: "omit", cache: "no-store",
          signal: controller.signal, headers: { Authorization: `Bearer ${bearer}`,
            Accept: json ? "application/json" : "application/octet-stream",
            ...(body ? { "Content-Type": json && path === "v1/persistence" ? "application/json" : "application/octet-stream" } : {}) }, body });
        if (response.redirected || response.status < 200 || response.status > 299
            || (response.url && new URL(response.url).href !== url.href)) fail("response_refused");
        const mime = (response.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
        if (mime !== (json ? "application/json" : "application/octet-stream")) fail("content_type_refused");
        const maximum = json ? 65_536 : maxRawBytes;
        const length = response.headers.get("content-length");
        if (length !== null && (!/^\d+$/.test(length) || BigInt(length) > BigInt(maximum))) fail("response_overflow");
        const chunks = []; let size = 0;
        if (!response.body) fail("response_empty");
        for await (const chunk of response.body) {
          size += chunk.length;
          if (size > maximum) fail("response_overflow");
          chunks.push(Buffer.from(chunk));
        }
        if (!size) fail("response_empty");
        const bytes = Buffer.concat(chunks);
        return json ? parseStrictJson(bytes, "sidecar_response") : bytes;
      } catch {
        // Never propagate upstream error strings, URL credentials, tokens or
        // token-file contents to API responses, logs or evidence.
        controller.abort();
        await response?.body?.cancel?.().catch(() => {});
        fail("sidecar_request_failed");
      } finally { clearTimeout(timer); }
    };
  }
  const publish = client(publisherURL, publisherToken);
  const read = client(readbackURL, readbackToken);
  return Object.freeze(validateSurvivabilityRuntimeV02({ lawBytes, lawSha256, chainId: 4663, configuredRelays,
    publisher: Object.freeze({
      publishDurable: (bytes) => publish("v1/durable", { method: "POST", body: bytes, json: true }),
      publishNostrPointer: (bytes) => publish("v1/nostr-pointer", { method: "POST", body: bytes, json: true }),
    }),
    readback: Object.freeze({
      readDurable: (locator) => read(`v1/durable?locator=${encodeURIComponent(locator)}`),
      confirmPersistence: async (locator, className) => (await read("v1/persistence", {
        method: "POST", body: jcsCanonicalize({ locator, class: className }), json: true })).confirmed === true,
      readNostrPointer: (relay, eventId) => read(`v1/nostr-pointer?relay=${encodeURIComponent(relay)}&eventId=${encodeURIComponent(eventId)}`),
    }),
  }));
}

import { jcsCanonicalize } from "../../packages/sdk/src/bermProtocolR13a.js";
import { parseStrictJson } from "../../packages/sdk/src/enrollmentProtocol.js";
import { decodeNpub } from "../../packages/sdk/src/identityCrypto.js";
import { robinhoodLeafHash, merkleNodeHash, verifyMerkleProof } from "../../packages/sdk/src/enrollmentRoster.js";
